#!/usr/bin/env python3
from __future__ import annotations

import argparse
import json
import re
import xml.etree.ElementTree as ET
from pathlib import Path


IMPORT_RE = re.compile(r"\b(?:import|export|part)\s+['\"]([^'\"]+)['\"]")
APP_RE = re.compile(r"\b(?:MaterialApp|CupertinoApp)\s*\(")
BANNER_FALSE_RE = re.compile(r"\bdebugShowCheckedModeBanner\s*:\s*false\b")
HIDDEN_SYSTEM_UI_RE = re.compile(
    r"SystemUiMode\.(?:immersiveSticky|immersive|leanBack)\b|"
    r"setEnabledSystemUIOverlays\s*\(\s*(?:const\s*)?\[\s*\]\s*\)"
)
SYSTEM_UI_MODE_CALL_RE = re.compile(
    r"\b[A-Za-z_][A-Za-z0-9_.]*\.setEnabledSystemUIMode\s*\("
)
SYSTEM_UI_STYLE_CALL_RE = re.compile(
    r"\b[A-Za-z_][A-Za-z0-9_.]*\.setSystemUIOverlayStyle\s*\("
)
ANNOTATED_STYLE_CALL_RE = re.compile(r"\bAnnotatedRegion\s*<\s*SystemUiOverlayStyle\s*>\s*\(")
RUN_APP_CALL_RE = re.compile(r"\brunApp\s*\(")
APPLY_DESIGN_POLICY_CALL_RE = re.compile(
    r"\b[A-Za-z_][A-Za-z0-9_.]*\.applyDesignPolicy\s*\("
)
SAFE_AREA_CALL_RE = re.compile(r"\bSafeArea\s*\(")
TOP_MEDIA_QUERY_RE = re.compile(
    r"MediaQuery\.(?:paddingOf|viewPaddingOf)\s*\([^)]*\)\s*\.top\b|"
    r"MediaQuery\.of\s*\([^)]*\)\.(?:padding|viewPadding)\.top\b"
)
TRANSPARENT_STATUS_BAR_RE = re.compile(
    r"statusBarColor\s*:\s*(?:const\s+)?(?:Colors\.transparent\b|Color\s*\(\s*0x00000000\s*\))"
)
GENERATED_POLICY_HEADER = "// GENERATED by iFF make_status_bar_policy.py; DO NOT EDIT."
POLICY_CLASS_RE = re.compile(r"\babstract\s+final\s+class\s+([A-Z][A-Za-z0-9]*)\s*\{")
POLICY_MODE_RE = re.compile(r"\bstatic\s+const\s+String\s+mode\s*=\s*'(overlay|hidden)'\s*;")
POLICY_DETECTED_RE = re.compile(
    r"\bstatic\s+const\s+bool\s+designStatusBarDetected\s*=\s*(true|false)\s*;"
)
POLICY_NO_TOP_INSET_RE = re.compile(
    r"\bstatic\s+const\s+bool\s+reserveTopInset\s*=\s*false\s*;"
)


def package_name(project_root: Path) -> str:
    pubspec = project_root / "pubspec.yaml"
    if not pubspec.is_file():
        return ""
    match = re.search(r"(?m)^name:\s*([A-Za-z0-9_]+)\s*$", pubspec.read_text(encoding="utf-8"))
    return match.group(1) if match else ""


def resolve_import(source: Path, uri: str, project_root: Path, package: str) -> Path | None:
    if uri.startswith("dart:"):
        return None
    if uri.startswith("package:"):
        prefix = f"package:{package}/"
        if not package or not uri.startswith(prefix):
            return None
        candidate = project_root / "lib" / uri[len(prefix):]
    else:
        candidate = source.parent / uri
    resolved = candidate.resolve()
    lib_root = (project_root / "lib").resolve()
    if resolved.suffix != ".dart" or not resolved.is_relative_to(lib_root) or not resolved.is_file():
        return None
    return resolved


def reachable_sources(entry: Path, project_root: Path) -> list[Path]:
    package = package_name(project_root)
    pending = [entry.resolve()]
    seen: set[Path] = set()
    while pending:
        source = pending.pop()
        if source in seen:
            continue
        seen.add(source)
        text = source.read_text(encoding="utf-8")
        imports = [resolve_import(source, uri, project_root, package) for uri in IMPORT_RE.findall(text)]
        pending.extend(sorted((path for path in imports if path is not None), reverse=True))
    return sorted(seen)


def constructor_body(text: str, start: int) -> str:
    open_index = text.find("(", start)
    depth = 0
    quote = ""
    escaped = False
    for index in range(open_index, len(text)):
        char = text[index]
        if quote:
            if escaped:
                escaped = False
            elif char == "\\":
                escaped = True
            elif char == quote:
                quote = ""
            continue
        if char in {"'", '"'}:
            quote = char
        elif char == "(":
            depth += 1
        elif char == ")":
            depth -= 1
            if depth == 0:
                return text[open_index:index + 1]
    return text[open_index:]


def top_level_arguments(call_body: str) -> str:
    """Return only first-level call arguments so nested `top:` values cannot mask a root SafeArea."""
    depth = 0
    quote = ""
    escaped = False
    result: list[str] = []
    for char in call_body:
        if quote:
            result.append(char if depth == 1 else " ")
            if escaped:
                escaped = False
            elif char == "\\":
                escaped = True
            elif char == quote:
                quote = ""
            continue
        if char in {"'", '"'}:
            quote = char
        elif char == "(":
            depth += 1
        elif char == ")":
            depth -= 1
        result.append(char if depth == 1 else " ")
    return "".join(result)


def system_ui_modes(text: str) -> set[str]:
    modes: set[str] = set()
    for match in SYSTEM_UI_MODE_CALL_RE.finditer(text):
        body = constructor_body(text, match.start())
        if re.search(r"\bSystemUiMode\.edgeToEdge\b", body):
            modes.add("overlay")
        elif re.search(r"\bSystemUiMode\.manual\b", body):
            has_bottom = re.search(r"\bSystemUiOverlay\.bottom\b", body) is not None
            has_top = re.search(r"\bSystemUiOverlay\.top\b", body) is not None
            modes.add("hidden" if has_bottom and not has_top else "invalid_hidden")
        elif re.search(r"\bSystemUiMode\.(?:immersiveSticky|immersive|leanBack)\b", body):
            modes.add("invalid_hidden")
    if HIDDEN_SYSTEM_UI_RE.search(text):
        modes.add("invalid_hidden")
    return modes


def parse_generated_policy(text: str) -> dict[str, object] | None:
    class_match = POLICY_CLASS_RE.search(text)
    mode_match = POLICY_MODE_RE.search(text)
    detected_match = POLICY_DETECTED_RE.search(text)
    if (
        not text.startswith(GENERATED_POLICY_HEADER)
        or class_match is None
        or mode_match is None
        or detected_match is None
        or POLICY_NO_TOP_INSET_RE.search(text) is None
    ):
        return None
    detected = detected_match.group(1) == "true"
    mode = mode_match.group(1)
    if detected != (mode == "overlay"):
        return None
    return {"className": class_match.group(1), "mode": mode, "designStatusBarDetected": detected}


def has_transparent_status_bar(text: str) -> bool:
    matches = [
        *SYSTEM_UI_STYLE_CALL_RE.finditer(text),
        *ANNOTATED_STYLE_CALL_RE.finditer(text),
    ]
    return any(
        TRANSPARENT_STATUS_BAR_RE.search(constructor_body(text, match.start()))
        for match in matches
    )


def reserves_top_inset(text: str) -> bool:
    for match in SAFE_AREA_CALL_RE.finditer(text):
        arguments = top_level_arguments(constructor_body(text, match.start()))
        if re.search(r"\btop\s*:\s*false\b", arguments) is None:
            return True
    if TOP_MEDIA_QUERY_RE.search(text):
        return True
    if re.search(r"\bappBar\s*:", text) and not re.search(
        r"\bextendBodyBehindAppBar\s*:\s*true\b",
        text,
    ):
        return True
    return False


def applies_status_bar_policy_before_run_app(text: str) -> bool:
    run_app = RUN_APP_CALL_RE.search(text)
    if run_app is None:
        return False
    startup = text[:run_app.start()]
    return bool(
        SYSTEM_UI_MODE_CALL_RE.search(startup)
        or APPLY_DESIGN_POLICY_CALL_RE.search(startup)
    )


def android_startup_theme_report(project_root: Path, mode: str) -> dict[str, object]:
    source_root = project_root / "android" / "app" / "src"
    if not source_root.is_dir():
        return {"checked": False, "ok": True, "mode": mode, "files": [], "issues": []}
    style_files = sorted(source_root.glob("*/res/values*/styles.xml"))
    issues: list[dict[str, str]] = []
    theme_counts = {"LaunchTheme": 0, "NormalTheme": 0}
    transparent_values = {"@android:color/transparent", "#00000000"}
    for path in style_files:
        try:
            root = ET.parse(path).getroot()
        except (OSError, ET.ParseError) as error:
            issues.append({"file": str(path), "style": "*", "issue": f"invalid_xml:{error}"})
            continue
        for style in root.findall("style"):
            style_name = style.attrib.get("name")
            if style_name not in theme_counts:
                continue
            theme_counts[style_name] += 1
            items = {
                item.attrib.get("name", ""): "".join(item.itertext()).strip()
                for item in style.findall("item")
            }
            parent = style.attrib.get("parent", "")
            if mode == "hidden":
                if items.get("android:windowFullscreen", "").lower() != "true":
                    issues.append(
                        {"file": str(path), "style": style_name, "issue": "windowFullscreen_not_true"}
                    )
                if "Fullscreen" not in parent:
                    issues.append(
                        {"file": str(path), "style": style_name, "issue": "fullscreen_parent_missing"}
                    )
                if items.get("android:windowDrawsSystemBarBackgrounds", "").lower() != "true":
                    issues.append(
                        {"file": str(path), "style": style_name, "issue": "drawsSystemBarBackgrounds_not_true"}
                    )
                if items.get("android:statusBarColor", "").lower() not in transparent_values:
                    issues.append(
                        {"file": str(path), "style": style_name, "issue": "statusBarColor_not_transparent"}
                    )
                if style_name == "LaunchTheme" and (
                    items.get("android:windowIsTranslucent", "").lower() != "true"
                    and "Translucent" not in parent
                ):
                    issues.append(
                        {"file": str(path), "style": style_name, "issue": "translucent_launch_theme_missing"}
                    )
                if (
                    style_name == "LaunchTheme"
                    and items.get("android:windowAnimationStyle", "").strip() != "@null"
                ):
                    issues.append(
                        {"file": str(path), "style": style_name, "issue": "launch_window_animation_not_disabled"}
                    )
            else:
                if items.get("android:windowFullscreen", "").lower() == "true" or "Fullscreen" in parent:
                    issues.append(
                        {"file": str(path), "style": style_name, "issue": "windowFullscreen_true"}
                    )
                if items.get("android:statusBarColor", "").lower() not in transparent_values:
                    issues.append(
                        {"file": str(path), "style": style_name, "issue": "statusBarColor_not_transparent"}
                    )
                if style_name == "LaunchTheme" and (
                    items.get("android:windowIsTranslucent", "").lower() == "true"
                    or "Translucent" in parent
                ):
                    issues.append(
                        {"file": str(path), "style": style_name, "issue": "translucent_launch_theme_present"}
                    )
                if items.get("android:windowDrawsSystemBarBackgrounds", "").lower() != "true":
                    issues.append(
                        {
                            "file": str(path),
                            "style": style_name,
                            "issue": "windowDrawsSystemBarBackgrounds_not_true",
                        }
                    )
    for style_name, count in theme_counts.items():
        if count == 0:
            issues.append({"file": str(source_root), "style": style_name, "issue": "style_missing"})
    return {
        "checked": True,
        "ok": not issues,
        "mode": mode,
        "files": [str(path) for path in style_files],
        "issues": issues,
    }


def android_startup_activity_report(project_root: Path, mode: str) -> dict[str, object]:
    source_root = project_root / "android" / "app" / "src"
    if not source_root.is_dir():
        return {"checked": False, "ok": True, "mode": mode, "files": [], "issues": []}

    activity_files: list[Path] = []
    activity_text: dict[Path, str] = {}
    for extension in ("kt", "java"):
        for path in sorted(source_root.glob(f"*/**/*.{extension}")):
            try:
                text = path.read_text(encoding="utf-8")
            except OSError:
                continue
            if "FlutterActivity" in text:
                activity_files.append(path)
                activity_text[path] = text

    issues: list[dict[str, str]] = []
    native_hide_files: list[str] = []
    for path, text in activity_text.items():
        on_create_parts = text.split("super.onCreate", 1)
        before_flutter = on_create_parts[0]
        after_flutter = on_create_parts[1] if len(on_create_parts) == 2 else ""
        has_fullscreen_flag = "FLAG_FULLSCREEN" in before_flutter and (
            ".setFlags(" in before_flutter or ".addFlags(" in before_flutter
        )
        has_unsafe_insets_hide = (
            "WindowInsets.Type.statusBars()" in before_flutter and ".hide(" in before_flutter
        )
        has_safe_insets_hide = (
            "WindowInsets.Type.statusBars()" in after_flutter and ".hide(" in after_flutter
        )
        has_splash_lifecycle_rehide = "onPostResume" in text and "onWindowFocusChanged" in text
        releases_rehide_after_flutter = (
            "onFlutterUiDisplayed" in text and "= true" in text and "= false" in text
        )
        if (
            has_fullscreen_flag
            and has_safe_insets_hide
            and not has_unsafe_insets_hide
            and has_splash_lifecycle_rehide
            and releases_rehide_after_flutter
        ):
            native_hide_files.append(str(path))
        if mode == "hidden" and has_unsafe_insets_hide:
            issues.append(
                {"file": str(path), "issue": "window_insets_hide_before_super_on_create"}
            )
        if mode == "hidden" and has_fullscreen_flag and has_safe_insets_hide and (
            not has_splash_lifecycle_rehide or not releases_rehide_after_flutter
        ):
            issues.append(
                {"file": str(path), "issue": "native_splash_lifecycle_hide_missing"}
            )
        if mode == "overlay" and (
            "FLAG_FULLSCREEN" in text or has_unsafe_insets_hide or has_safe_insets_hide
        ):
            issues.append(
                {"file": str(path), "issue": "native_forced_status_bar_hide_present"}
            )

    if mode == "hidden" and not native_hide_files:
        issues.append(
            {"file": str(source_root), "issue": "native_status_bar_pre_hide_missing"}
        )
    return {
        "checked": True,
        "ok": not issues,
        "mode": mode,
        "files": [str(path) for path in activity_files],
        "nativeHideFiles": native_hide_files,
        "issues": issues,
    }


def main() -> int:
    parser = argparse.ArgumentParser(description="Verify the real Flutter app entry disables the debug banner before capture")
    parser.add_argument("--project-root", required=True)
    parser.add_argument("--entry", required=True)
    parser.add_argument("--out", required=True)
    parser.add_argument("--scene")
    parser.add_argument("--page-source", action="append", default=[])
    parser.add_argument("--safe-area-source", action="append", default=[])
    parser.add_argument("--policy-source")
    parser.add_argument("--startup-policy-source")
    args = parser.parse_args()

    project_root = Path(args.project_root).resolve()
    entry = Path(args.entry).resolve()
    out = Path(args.out).resolve()
    out.parent.mkdir(parents=True, exist_ok=True)
    if not entry.is_file() or not entry.is_relative_to(project_root / "lib"):
        report = {"ok": False, "reason": "invalid_entry", "entry": str(entry)}
        out.write_text(json.dumps(report, indent=2) + "\n", encoding="utf-8")
        print(f"ERROR: invalid Flutter entry: {entry}")
        return 2

    entry_text = entry.read_text(encoding="utf-8")
    reachable = reachable_sources(entry, project_root)
    initial_policy_applied_before_run_app = applies_status_bar_policy_before_run_app(entry_text)
    status_bar_required = False
    scene_path = Path(args.scene).resolve() if args.scene else None
    status_bar_policy_checked = scene_path is not None
    if scene_path is not None:
        if not scene_path.is_file() or not scene_path.is_relative_to(project_root):
            report = {"ok": False, "reason": "invalid_scene", "scene": str(scene_path)}
            out.write_text(json.dumps(report, indent=2) + "\n", encoding="utf-8")
            return 2
        scene = json.loads(scene_path.read_text(encoding="utf-8"))
        status_bar_required = any(
            isinstance(item, dict) and item.get("role") == "status_bar"
            for item in scene.get("systemUiExclusions") or []
        )
    hidden_system_ui_files = [
        str(source) for source in reachable if HIDDEN_SYSTEM_UI_RE.search(source.read_text(encoding="utf-8"))
    ]
    page_sources: list[Path] = []
    invalid_page_sources: list[str] = []
    for value in [*args.page_source, *args.safe_area_source]:
        source = Path(value).resolve()
        if source.is_file() and source.is_relative_to(project_root / "lib"):
            if source not in page_sources:
                page_sources.append(source)
        else:
            invalid_page_sources.append(str(source))
    page_text = {source: source.read_text(encoding="utf-8") for source in page_sources}
    top_inset_sources = [str(source) for source, text in page_text.items() if reserves_top_inset(text)]
    reachable_text = {source: source.read_text(encoding="utf-8") for source in reachable}
    policy_source_path = Path(args.policy_source).resolve() if args.policy_source else None
    policy_source: dict[str, object] | None = None
    if policy_source_path is not None:
        if policy_source_path.is_file() and policy_source_path.is_relative_to(project_root / "lib"):
            policy_source = parse_generated_policy(policy_source_path.read_text(encoding="utf-8"))
        if policy_source is None:
            invalid_page_sources.append(str(policy_source_path))
    startup_policy_source_path = (
        Path(args.startup_policy_source).resolve() if args.startup_policy_source else policy_source_path
    )
    startup_policy_source: dict[str, object] | None = policy_source
    invalid_startup_policy_source = False
    if startup_policy_source_path is not None and startup_policy_source_path != policy_source_path:
        if startup_policy_source_path.is_file() and startup_policy_source_path.is_relative_to(project_root / "lib"):
            startup_policy_source = parse_generated_policy(
                startup_policy_source_path.read_text(encoding="utf-8")
            )
        else:
            startup_policy_source = None
        invalid_startup_policy_source = startup_policy_source is None
    page_mode_sources = {source: text for source, text in page_text.items() if system_ui_modes(text)}
    policy_text = page_mode_sources or reachable_text
    modes_by_file = {
        str(source): sorted(modes)
        for source, text in policy_text.items()
        if (modes := system_ui_modes(text))
    }
    implemented_modes = {mode for modes in modes_by_file.values() for mode in modes}
    overlay_mode_files = [source for source, modes in modes_by_file.items() if "overlay" in modes]
    hidden_status_bar_files = [source for source, modes in modes_by_file.items() if "hidden" in modes]
    invalid_hidden_mode_files = [source for source, modes in modes_by_file.items() if "invalid_hidden" in modes]
    transparent_status_bar_files = [
        str(source) for source, text in {**reachable_text, **page_text}.items() if has_transparent_status_bar(text)
    ]
    expected_mode = "overlay" if status_bar_required else "hidden"
    startup_mode = str(startup_policy_source["mode"]) if startup_policy_source else expected_mode
    android_startup_theme = android_startup_theme_report(project_root, startup_mode)
    android_startup_activity = android_startup_activity_report(project_root, startup_mode)
    policy_binding_files: list[str] = []
    if policy_source:
        binding_token = f"{policy_source['className']}.designStatusBarDetected"
        policy_binding_files = [
            str(source)
            for source, text in {**reachable_text, **page_text}.items()
            if source != policy_source_path and binding_token in text
        ]
    page_consumes_policy = any("designStatusBarDetected" in text for text in page_text.values())
    policy_bound = bool(policy_binding_files and page_consumes_policy)
    app_shell_files: list[str] = []
    safe_files: list[str] = []
    for source in reachable:
        text = source.read_text(encoding="utf-8")
        matches = list(APP_RE.finditer(text))
        if not matches:
            continue
        app_shell_files.append(str(source))
        if all(BANNER_FALSE_RE.search(constructor_body(text, match.start())) for match in matches):
            safe_files.append(str(source))

    if invalid_page_sources:
        ok = False
        reason = "invalid_page_source"
    elif invalid_startup_policy_source:
        ok = False
        reason = "invalid_startup_policy_source"
    elif not app_shell_files:
        ok = False
        reason = "app_shell_not_found"
    elif sorted(app_shell_files) != sorted(safe_files):
        ok = False
        reason = "debug_banner_not_disabled"
    elif policy_source_path is not None and not status_bar_policy_checked:
        ok = False
        reason = "status_bar_policy_requires_scene"
    elif policy_source and policy_source["mode"] != expected_mode:
        ok = False
        reason = "status_bar_policy_scene_mismatch"
    elif policy_source and not policy_bound:
        ok = False
        reason = "status_bar_policy_not_bound"
    elif status_bar_policy_checked and not initial_policy_applied_before_run_app:
        ok = False
        reason = "status_bar_policy_applied_after_run_app"
    elif status_bar_policy_checked and not android_startup_theme["ok"]:
        ok = False
        reason = "android_launch_theme_status_bar_flash"
    elif status_bar_policy_checked and not android_startup_activity["ok"]:
        ok = False
        reason = "android_launch_activity_status_bar_flash"
    elif status_bar_policy_checked and len(implemented_modes) > 1 and policy_source is None:
        ok = False
        reason = "ambiguous_status_bar_policy"
    elif status_bar_policy_checked and status_bar_required and (
        hidden_system_ui_files or invalid_hidden_mode_files
    ):
        ok = False
        reason = "system_status_bar_hidden"
    elif status_bar_policy_checked and status_bar_required and not overlay_mode_files:
        ok = False
        reason = "status_bar_overlay_mode_missing"
    elif status_bar_policy_checked and status_bar_required and not transparent_status_bar_files:
        ok = False
        reason = "status_bar_transparency_missing"
    elif status_bar_policy_checked and status_bar_required and top_inset_sources:
        ok = False
        reason = "status_bar_content_not_behind"
    elif status_bar_policy_checked and not status_bar_required and invalid_hidden_mode_files:
        ok = False
        reason = "status_bar_hide_mode_invalid"
    elif status_bar_policy_checked and not status_bar_required and not hidden_status_bar_files:
        ok = False
        reason = "unexpected_system_status_bar"
    elif status_bar_policy_checked and not status_bar_required and top_inset_sources:
        ok = False
        reason = "top_inset_reserved_without_status_bar"
    else:
        ok = True
        reason = None
    report = {
        "ok": ok,
        "reason": reason,
        "entry": str(entry),
        "reachableFiles": [str(path) for path in reachable],
        "appShellFiles": app_shell_files,
        "bannerSafeFiles": safe_files,
        "designStatusBarDetected": status_bar_required,
        "statusBarPolicyChecked": status_bar_policy_checked,
        "initialPolicyAppliedBeforeRunApp": initial_policy_applied_before_run_app,
        "statusBarPolicy": (
            {
                "mode": "overlay" if status_bar_required else "hidden",
                "visible": status_bar_required,
                "transparent": status_bar_required,
                "overlaysContent": status_bar_required,
                "reserveTopInset": False,
            }
            if status_bar_policy_checked
            else None
        ),
        "hiddenSystemUiFiles": hidden_system_ui_files,
        "policySource": policy_source,
        "policySourcePath": str(policy_source_path) if policy_source_path else None,
        "startupPolicySource": startup_policy_source,
        "startupPolicySourcePath": str(startup_policy_source_path) if startup_policy_source_path else None,
        "androidStartupTheme": android_startup_theme,
        "androidStartupActivity": android_startup_activity,
        "policyBound": policy_bound,
        "policyBindingFiles": policy_binding_files,
        "pageSources": [str(source) for source in page_sources],
        "invalidPageSources": invalid_page_sources,
        "topInsetSources": top_inset_sources,
        "safeAreaSources": top_inset_sources,
        "policyEvidenceScope": "page" if page_mode_sources else "entry_graph",
        "systemUiModesByFile": modes_by_file,
        "overlayModeFiles": overlay_mode_files,
        "hiddenStatusBarFiles": hidden_status_bar_files,
        "invalidHiddenModeFiles": invalid_hidden_mode_files,
        "transparentStatusBarFiles": transparent_status_bar_files,
    }
    out.write_text(json.dumps(report, indent=2) + "\n", encoding="utf-8")
    if ok:
        print(f"ok capture readiness: {len(app_shell_files)} reachable app shell file(s)")
        return 0
    print(f"ERROR: capture readiness failed: {reason}")
    return 1


if __name__ == "__main__":
    raise SystemExit(main())
